#!/usr/bin/env node
/**
 * Independent authority and source contract for Sycamore Creek Bridge.
 * Keeps this Tarrant County 1936 concrete crossing distinct from Texas's
 * older Hamilton County truss of the same name and the North Carolina park
 * bridge. No autogenerated tourism access claims.
 */
import fs from "node:fs";

const file = fs.readFileSync("src/data/thc-sycamore-creek-bridge-fort-worth.ts","utf8");
const destinations = fs.readFileSync("src/data/destination-preserved-catalog.ts","utf8");
const pairings = fs.readFileSync("src/data/destination-curated-pairings.ts","utf8");
const index = fs.readFileSync("src/routes/texas-historic-landmarks.lazy.tsx","utf8");
const errors=[];
if (!destinations.includes("sycamoreCreekBridgeFortWorthAuthority")) errors.push("Destination not published in canonical Explore");
if (!pairings.includes('"sycamore-creek-bridge-fort-worth"')) errors.push("No reciprocal historic-city relationship");
if (!index.includes('"Sycamore Creek Bridge": "sycamore-creek-bridge-fort-worth"')) errors.push("Missing THC index to authority guide link");
if (!file.includes('slug:"sycamore-creek-bridge-fort-worth"')) errors.push("Wrong canonical slug");
if (!file.includes("100012723")||!file.includes("1936")||!file.includes("C. Milo Thelin")) errors.push("Missing distinguishing designation or architect");
if (!file.includes("commonsFilePage(photo)")||!file.includes("CC BY-SA 4.0")) errors.push("Photo rights/credit source missing");
const body=file.split('  body:[')[1]?.split('  faqs:[')[0]||"";
const faqs=file.split('  faqs:[')[1]?.split('  sources:[')[0]||"";
const sources=file.split('  sources:[')[1]?.split('  whyVisit:')[0]||"";
if((body.match(/^    "/gm)||[]).length<7||body.length<4300)errors.push("Insufficient research narrative");
if((faqs.match(/thcFaq\(/g)||[]).length<7)errors.push("Insufficient FAQs");
if((sources.match(/thcSource\(/g)||[]).length<5)errors.push("Insufficient cited sources");
if(!file.includes("Do not stop")||!file.includes("accessibility:"))errors.push("Road safety and access rules absent");
console.log(JSON.stringify({site:"sycamore-creek-bridge-fort-worth",passed:errors.length===0,errors},null,2));
if(errors.length)process.exitCode=1;
